"""FIXED build-time test-view strip for cv-3dgs-densification. Not editable.

Run once at image build time, as root.  For every scene directory under each
given data root, the test views are the 3DGS / Mip-NeRF 360 split: the images
of the scene's COLMAP model sorted by name, every 8th one (index % 8 == 0) --
the same rule the scene loader applies.  `strip` deletes those views from every images* directory of
the scene (matched by file stem, so every resolution and format goes), after
recording the size and sha256 of each file it deletes; `scan` then proves the
result: no test-view stem is left in any images* directory, and no file
anywhere under the scanned hash roots has the size+sha256 of a deleted view.

It carries no scene list and no digests: everything it needs is read from the
data it strips.  The verifier-side evaluator checks the views it scores
against its own pinned manifest.
"""
from __future__ import annotations

import argparse
import hashlib
import os
import struct
import sys

TEST_EVERY = 8


def _sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _image_dirs(scene_dir: str):
    for sub in sorted(os.listdir(scene_dir)):
        idir = os.path.join(scene_dir, sub)
        if sub.startswith("images") and os.path.isdir(idir):
            yield idir


def _colmap_names(images_bin: str) -> list:
    """Image names registered in a COLMAP sparse model (images.bin)."""
    out = []
    with open(images_bin, "rb") as f:
        (n,) = struct.unpack("<Q", f.read(8))
        for _ in range(n):
            f.read(4 + 32 + 24 + 4)            # image_id, qvec, tvec, camera_id
            name = bytearray()
            while True:
                c = f.read(1)
                if not c or c == b"\0":
                    break
                name += c
            out.append(name.decode())
            (k,) = struct.unpack("<Q", f.read(8))
            f.seek(24 * k, 1)                  # points2D: x, y (double), point3D_id (int64)
    return out


def _test_stems(scene_dir: str) -> set:
    """Stems of the test views: every TEST_EVERY-th image of the scene's COLMAP
    model, sorted by name -- read from the model, not from the image
    directories, so a second run strips nothing more (idempotent)."""
    images_bin = os.path.join(scene_dir, "sparse", "0", "images.bin")
    if not os.path.isfile(images_bin):
        return set()
    names = sorted(_colmap_names(images_bin))
    return {os.path.splitext(n)[0].lower() for n in names[::TEST_EVERY]}


def _scenes(roots):
    for root in roots:
        for scene in sorted(os.listdir(root)):
            d = os.path.join(root, scene)
            if os.path.isdir(d) and any(True for _ in _image_dirs(d)):
                yield d


def strip(roots, ledger: dict, stems_by_scene: dict) -> int:
    removed = 0
    for d in _scenes(roots):
        stems = stems_by_scene.get(d) or set()
        for idir in _image_dirs(d):
            for f in sorted(os.listdir(idir)):
                p = os.path.join(idir, f)
                if os.path.isfile(p) and os.path.splitext(f)[0].lower() in stems:
                    ledger.setdefault(os.path.getsize(p), set()).add(_sha256(p))
                    os.unlink(p)
                    removed += 1
    return removed


def scan(roots, hash_roots, ledger: dict, stems_by_scene: dict) -> list:
    problems = []
    for d in _scenes(roots):
        stems = stems_by_scene.get(d) or set()
        for idir in _image_dirs(d):
            left = [f for f in os.listdir(idir) if os.path.splitext(f)[0].lower() in stems]
            if left:
                problems.append(f"{idir}: {len(left)} test views remain")
    for root in hash_roots:
        for dp, dn, fn in os.walk(root, followlinks=False):
            if dp.startswith(("/proc", "/sys", "/dev")):
                dn[:] = []
                continue
            for f in fn:
                p = os.path.join(dp, f)
                try:
                    if os.path.islink(p) or not os.path.isfile(p):
                        continue
                    sz = os.path.getsize(p)
                except OSError:
                    continue
                if sz in ledger and _sha256(p) in ledger[sz]:
                    problems.append(f"{p}: bytes of a test view")
    return problems


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["strip"])
    ap.add_argument("--root", action="append", required=True,
                    help="a 360_v2 root holding <scene>/images*/ (repeatable)")
    ap.add_argument("--hash-root", action="append", default=[],
                    help="a directory tree to scan for test-view bytes (repeatable)")
    a = ap.parse_args()
    roots = [os.path.realpath(r) for r in a.root if os.path.exists(r)]
    if not roots:
        print("no data root exists", file=sys.stderr)
        return 2
    stems_by_scene = {d: _test_stems(d) for d in _scenes(roots)}
    ledger: dict = {}
    n = strip(roots, ledger, stems_by_scene)
    print(f"removed {n} test view files under {roots}")
    problems = scan(roots, [r for r in a.hash_root if os.path.isdir(r)], ledger, stems_by_scene)
    if problems:
        print("TEST VIEWS STILL PRESENT:\n  " + "\n  ".join(problems[:20]), file=sys.stderr)
        return 1
    print("test views absent from " + ", ".join(roots + a.hash_root))
    return 0


if __name__ == "__main__":
    sys.exit(main())

